# Shared settings for the lab PowerShell scripts. Dot-source this file; do not run it.
$LabEnvDir = $PSScriptRoot
$LabRoot = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$Compose = @('compose', '-f', (Join-Path $LabEnvDir 'docker-compose.yml'))
$Ase = 'cdc-lab-sybase'; $Kafka = 'cdc-lab-kafka'; $Connect = 'cdc-lab-connect'
$ConnectUrl = 'http://localhost:8083'
$ConnectorName = 'sybase-cdc-phoenix'
$Topic = if ($env:TOPIC) { $env:TOPIC } else { 'sybase.phoenix_test.payment' }
$SaPassword = 'myPassword'   # public default of the ASE image (not a secret); used only for one-time setup

# Passwords of the lab accounts are generated by create-accounts.ps1 into this git-ignored file (KEY=VALUE lines).
$LabSecrets = Join-Path $LabEnvDir '.lab-secrets'
if (Test-Path $LabSecrets) {
  Get-Content $LabSecrets | ForEach-Object {
    if ($_ -match '^(\w+)=(.*)$') { Set-Variable -Name $Matches[1] -Value $Matches[2] }
  }
}

# isql against the lab database; SQL text as the argument.
# -As: sa (setup and DDL only), admin (replication_role only), app (DML on the sample tables only).
function Invoke-AseSql([string]$Sql, [ValidateSet('sa', 'admin', 'app')][string]$As = 'sa') {
  switch ($As) {
    'sa'    { $u = 'sa';        $p = $SaPassword }
    'admin' { $u = 'cdc_admin'; $p = $CDC_ADMIN_PASSWORD }
    'app'   { $u = 'cdc_app';   $p = $CDC_APP_PASSWORD }
  }
  if (-not $p) { throw 'Lab account passwords missing: run lab\env\create-accounts.ps1 first' }
  # Windows PowerShell pipes text with CRLF line endings, and isql does not see "go\r" as a batch end. So the SQL is
  # normalised to LF, sent base64-encoded as an argument and decoded inside the container.
  $text = $Sql.Replace("`r`n", "`n").TrimEnd() + "`n"
  $b64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($text))
  docker exec $Ase bash -c "source /opt/sybase/SYBASE.sh; echo $b64 | base64 -d | isql -U$u -P$p -SMYSYBASE -w250 -Dphoenix_test" | Where-Object { $_.Trim() }
}

function Wait-For([string]$What, [int]$TimeoutSec, [scriptblock]$Test) {
  $t = 0
  while ($true) {
    try { if (& $Test) { Write-Host "ok: $What"; return } } catch {}
    $t += 3; if ($t -ge $TimeoutSec) { throw "TIMEOUT waiting for $What" }
    Start-Sleep 3
  }
}
